export type FieldName = keyof CustomerForm;
export type FieldErrors = Record<FieldName, string | null>;

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export function validate(v: CustomerForm): FieldErrors {
